const $=id=>document.getElementById(id);const MAX_BATCH_IMAGES=10;const COASTERLAB_BUILD='coasterlab-r23';let items=[],mode='color',busy=false,nextId=0;const sizes=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.round(n/1024)+' KB';
function render(){ $('queue').replaceChildren();for(const item of items){const card=document.createElement('div');card.className='card';const thumb=document.createElement('div');thumb.className='thumb';const img=document.createElement('img');img.src=item.svgUrl||item.url;img.alt=item.svg?'Traced '+item.file.name:item.file.name;thumb.append(img);const info=document.createElement('div');info.className='info';const name=document.createElement('div');name.className='name';name.textContent=item.file.name;name.title=item.file.name;const status=document.createElement('div');status.className='status'+(item.error?' error':'');status.textContent=item.error||item.status;if(item.traceStale&&item.svg)status.textContent='Settings changed — retrace artwork to update this preview.';if(item.traceAdvice&&!item.traceStale)status.textContent+='\n'+item.traceAdvice;if(item.stl){const box=item.stl.dimensions;status.textContent+='\n3D: '+(box.max[0]-box.min[0]).toFixed(1)+' × '+(box.max[1]-box.min[1]).toFixed(1)+' × '+(box.max[2]-box.min[2]).toFixed(1)+' mm';}if(item.stl?.warnings?.length)status.textContent+='\n'+item.stl.warnings.join(' ');if(item.stlError)status.textContent+='\nSTL: '+item.stlError;const actions=document.createElement('div');actions.className='actions';if(item.svg){const dl=document.createElement('button');dl.textContent='↓ Download SVG';dl.disabled=busy||!!item.traceStale;dl.onclick=()=>download(item.svgUrl,item.outname);actions.append(dl);const compare=document.createElement('button');compare.textContent='View original';compare.onclick=()=>{const original=img.src===item.url;img.src=original?item.svgUrl:item.url;compare.textContent=original?'View original':'View SVG';};actions.append(compare);if(item.stl){for(const [label,url,name]of [['↓ Bambu 3MF',item.threeMFUrl,item.outname.replace(/\.svg$/,'.3mf')],['↓ STL (merged)',item.stlUrl,item.outname.replace(/\.svg$/,'.stl')],['↓ STL parts ZIP',item.partsUrl,item.outname.replace(/\.svg$/,'-color-parts.zip')]]){if(!url)continue;const btn=document.createElement('button');btn.textContent=label;btn.onclick=()=>download(url,name);actions.append(btn);}}}else{const remove=document.createElement('button');remove.textContent='Remove';remove.disabled=busy;remove.onclick=()=>{URL.revokeObjectURL(item.url);items=items.filter(x=>x!==item);render();};actions.append(remove);}info.append(name,status,actions);card.append(thumb,info);$('queue').append(card);}const ready=items.filter(x=>x.svg&&!x.traceStale).length;$('empty').hidden=items.length>0;$('trace').disabled=!items.length||busy;$('clear').disabled=!items.length||busy;$('download').disabled=!ready||busy;$('buildSTL').disabled=!ready||busy;const models=items.filter(i=>i.stl).length;$('downloadSTL').disabled=!items.some(i=>i.stl?.combined)||busy;$('download3MF').disabled=!models||busy;$('download3MF').textContent=models>1?'↓ Multi-plate 3MF':'↓ Bambu 3MF';$('downloadSTL').textContent=models>1?'↓ 3D models ZIP':'↓ Merged STL';$('total').textContent=items.length?' / '+items.length+' images':'';$('summary').textContent=items.length?ready+' of '+items.length+' ready to download':'Your coaster starts with an image.';$('download').textContent=ready===1?'↓ Download SVG':'↓ Download ZIP';$('trace').textContent=busy?'Tracing artwork…':items.some(i=>i.svg)?'Retrace artwork →':'Trace coaster artwork →';for(const id of ['bw','color','colors','threshold','detail','files','removeBackground','smoothOuter','cleanEdgeSpecks','sealOuterRim','edgeStrength','pinholeArea','autoSTL','modelWidth','baseHeight','topHeight'])$(id).disabled=busy;$('edgeStrength').disabled=busy||!$('smoothOuter').checked;if(typeof updateBatchControls==='function')updateBatchControls();}
async function addFiles(files){if(busy)return;let errors=[];for(const file of files){if(!/\.(png|jpe?g)$/i.test(file.name)){errors.push(file.name+': use JPG or PNG.');continue;}if(file.size>20*1024*1024){errors.push(file.name+': exceeds 20 MB.');continue;}if(items.length>=MAX_BATCH_IMAGES){errors.push('Batch limit is 10 images. Clear the current batch before adding more.');break;}items.push({id:++nextId,file,url:URL.createObjectURL(file),status:sizes(file.size)+' · Ready to trace'});}$('notice').textContent=errors.join(' ')||items.length+' images added. Pick your coaster colors, then trace.';render();$('files').value='';}
$('files').onchange=e=>addFiles(e.target.files);$('drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('files').click();}};for(const event of ['dragover','dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.toggle('over',event==='dragover');if(event==='drop')addFiles(e.dataTransfer.files);});
for(const m of ['bw','color'])$(m).onclick=()=>{mode=m;for(const n of ['bw','color']){$(n).classList.toggle('active',n===m);$(n).setAttribute('aria-pressed',n===m);}$('colorsbox').hidden=m==='bw';$('thresholdbox').hidden=m!=='bw';};$('colors').oninput=e=>$('count').textContent=e.target.value;$('threshold').oninput=e=>$('thresholdvalue').textContent=e.target.value;
$('clear').onclick=()=>{for(const item of items){clearSTL(item);URL.revokeObjectURL(item.url);if(item.svgUrl)URL.revokeObjectURL(item.svgUrl);}items=[];$('notice').textContent='Add an image to start your coaster.';render();};
function traceWorker(data){const runId='trace-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);return new Promise((resolve,reject)=>{const worker=new Worker('worker.478fd38177fc.js');const timer=setTimeout(()=>{worker.terminate();reject(new Error('Tracing took too long. Try smoother detail or a smaller image.'));},120000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();if(e.data.error){reject(new Error(e.data.error));return;}if(e.data.build!==COASTERLAB_BUILD||e.data.runId!==runId){reject(new Error('A stale tracing script was loaded. Open coasterlab-r23.html and retrace.'));return;}resolve(e.data);};worker.onerror=()=>{clearTimeout(timer);worker.terminate();reject(new Error('Unable to run the tracing engine.'));};worker.postMessage({...data,runId},[data.pixels.buffer]);});}
$('trace').onclick=async()=>{let printSettings=null;if($('autoSTL').checked){try{printSettings=stlSettings();}catch(e){$('notice').textContent=e.message;return;}}busy=true;let failures=0;const settings={mode,colors:+$('colors').value,threshold:+$('threshold').value,detail:$('detail').value,removeBackground:$('removeBackground').checked,smoothOuter:$('smoothOuter').checked,cleanEdgeSpecks:$('cleanEdgeSpecks').checked,sealOuterRim:$('sealOuterRim').checked,edgeStrength:$('edgeStrength').value,pinholeArea:+$('pinholeArea').value};for(let n=0;n<items.length;n++){const item=items[n];item.error=null;item.traceAdvice=null;item.traceInfo=null;item.traceStale=true;clearSTL(item);item.svg=null;const traceStarted=performance.now();if(item.svgUrl){URL.revokeObjectURL(item.svgUrl);item.svgUrl=null;}item.status='Tracing artwork…';$('notice').textContent='Tracing image '+(n+1)+' of '+items.length+'…';render();try{const bitmap=await createImageBitmap(item.file);if(bitmap.width*bitmap.height>80000000){bitmap.close();throw new Error('Image is too large to decode safely. Resize it first.');}const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const width=Math.max(1,Math.round(bitmap.width*scale)),height=Math.max(1,Math.round(bitmap.height*scale));const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,width,height);bitmap.close();const traceResult=await traceWorker({id:item.id,pixels:ctx.getImageData(0,0,width,height).data,width,height,...settings});item.svg=traceResult.svg;item.traceInfo=traceResult;item.traceStale=false;item.svgUrl=URL.createObjectURL(new Blob([item.svg],{type:'image/svg+xml'}));item.outname=String(n+1).padStart(2,'0')+'-'+item.file.name.replace(/\.[^.]+$/,'')+'.svg';const info=item.traceInfo,sm=info.smoothing;item.status='SVG regenerated · r23 · '+new Date(info.createdAt).toLocaleTimeString()+' · '+Math.round(performance.now()-traceStarted)+' ms\n'+(sm.enabled?sm.strength+' edge · '+sm.movedPoints+' boundary points adjusted':'Edge smoothing off')+' · '+(info.edgeCleanup?.removedComponents||0)+' edge flecks removed'+(info.rimSealPx?' · rim sealed':'')+' · geometry '+info.geometryHash+(scale<1?'\nTraced at '+width+' × '+height:'');if(sm.enabled&&!sm.exteriorTransparentPixels)item.traceAdvice='Tip: no transparent outside background was found. If your coaster has a curved outline inside a solid background, enable Remove edge background and retrace to expose it.';else if(sm.enabled&&!sm.movedPoints)item.traceAdvice='This setting adjusted 0 perimeter points. Try Strong if the edge still looks rough.';if(printSettings){$('notice').textContent='Building 3D model '+(n+1)+' of '+items.length+'…';render();await generateItemSTL(item,printSettings);}}catch(e){item.error=e.message||'Could not process this image.';failures++;}render();}busy=false;$('notice').textContent=failures?failures+' image(s) failed. Successful SVGs are available to download.':items.some(i=>i.stlError)?items.filter(i=>i.stlError).map(i=>i.file.name+': '+i.stlError).join(' | '):printSettings?'All done. SVGs, Bambu 3MFs and STL downloads are ready.':'All done. Your SVGs are ready to download.';render();};
function download(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click();}$('download').onclick=()=>{const ready=items.filter(x=>x.svg&&!x.traceStale);if(ready.length===1){download(ready[0].svgUrl,ready[0].outname);return;}const files={};for(const item of ready)files[item.outname]=fflate.strToU8(item.svg);const url=URL.createObjectURL(new Blob([fflate.zipSync(files,{level:6})],{type:'application/zip'}));download(url,'coasterlab-svgs.zip');setTimeout(()=>URL.revokeObjectURL(url),30000);};

$('smoothOuter').addEventListener('change',()=>{$('edgeStrength').disabled=busy||!$('smoothOuter').checked;});

function invalidateTraceOutputs(){if(busy)return;let changed=false;for(const item of items){if(!item.svg)continue;item.traceStale=true;clearSTL(item);changed=true;}if(changed){$('notice').textContent='Tracing settings changed. Click Retrace artwork to create a fresh SVG and 3MF. Build / rebuild coaster uses the SVG and cannot apply new tracing settings.';render();}}
for(const id of ['colors','threshold'])$(id).addEventListener('input',invalidateTraceOutputs);
for(const id of ['detail','removeBackground','smoothOuter','cleanEdgeSpecks','sealOuterRim','edgeStrength','pinholeArea'])$(id).addEventListener('change',invalidateTraceOutputs);
for(const id of ['bw','color'])$(id).addEventListener('click',invalidateTraceOutputs);
